function breakdownOf(tokens: number, overhead: number, rawMax: number | null = null): Any {
  const a = Math.round(overhead * 0.22)
  const b = Math.round(overhead * 0.41)
  const c = Math.round(overhead * 0.15)
  const d = Math.round(overhead * 0.13)
  const e = overhead - a - b - c - d
  const row = (name: string, n: number, kind: string) => ({ name, tokens: n, color: 'inactive', isDeferred: false, kind })
  return {
    categories: [
      row('System prompt', a, 'used'),
      row('System tools', b, 'used'),
      row('MCP tools', c, 'used'),
      row('Memory files', d, 'used'),
      row('Skills', e, 'used'),
      row('Messages', tokens - overhead, 'used'),
      row('Free space', WINDOW - tokens - 45_000, 'free'),
      row('Autocompact buffer', 45_000, 'buffer'),
    ],
    totalTokens: tokens,
    maxTokens: WINDOW,
    rawMaxTokens: rawMax ?? WINDOW,
    percentage: Math.round(tokens / 10_000),
    gridRows: [],
    model: 'x',
    memoryFiles: [],
    mcpTools: [],
    agents: [],
    isAutoCompactEnabled: true,
    apiUsage: null,
  }
}

